from __future__ import annotations

from pathlib import Path

from .config import GO2RTC_PATH, GO2RTC_URL, ensure_dirs


def write_go2rtc_config(channels: list[dict], use_vaapi: bool = True) -> Path:
    """Generate go2rtc.yaml from channel RTSP URLs."""
    ensure_dirs()
    lines = [
        "# Generated by mariiy-agent — do not edit by hand",
        "api:",
        "  listen: \":1984\"",
        "  origin: \"*\"",
        "rtsp:",
        "  listen: \":8554\"",
        "webrtc:",
        "  listen: \":8555\"",
        "ffmpeg:",
        "  bin: ffmpeg",
    ]
    if use_vaapi:
        lines += [
            "  # Intel VAAPI when /dev/dri is present",
            "  hwaccel: vaapi",
            "  hwaccel_device: /dev/dri/renderD128",
        ]
    lines.append("streams:")

    for ch in channels:
        cid = ch.get("id") or ch.get("slot")
        name = f"ch{int(cid):02d}"
        sub = ch.get("subUri") or ch.get("mainUri") or ""
        main = ch.get("mainUri") or ch.get("subUri") or ""
        if not sub and not main:
            continue
        # Substream for grid; main for single view
        if sub:
            # TCP + copy for low CPU; VAAPI hwaccel used when go2rtc must decode
            src = _rtsp_tcp(sub)
            if use_vaapi:
                lines.append(f"  {name}: ffmpeg:{src}#video=copy#audio=copy")
            else:
                lines.append(f"  {name}: ffmpeg:{src}#video=copy#audio=copy")
        if main and main != sub:
            src = _rtsp_tcp(main)
            lines.append(f"  {name}_main: ffmpeg:{src}#video=copy#audio=copy")
        elif main and not sub:
            src = _rtsp_tcp(main)
            lines.append(f"  {name}: ffmpeg:{src}#video=copy#audio=copy")
            lines.append(f"  {name}_main: ffmpeg:{src}#video=copy#audio=copy")

    GO2RTC_PATH.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return GO2RTC_PATH


def _rtsp_tcp(uri: str) -> str:
    if not uri.startswith("rtsp://"):
        return uri
    sep = "&" if "?" in uri else "?"
    if "rtsp_transport=" in uri:
        return uri
    return f"{uri}{sep}rtsp_transport=tcp"


def stream_page_url(channel_id: int, main: bool = False) -> str:
    name = f"ch{int(channel_id):02d}"
    if main:
        name = f"{name}_main"
    # go2rtc built-in player / WebRTC page
    return f"{GO2RTC_URL}/stream.html?src={name}"


def mse_url(channel_id: int, main: bool = False) -> str:
    name = f"ch{int(channel_id):02d}"
    if main:
        name = f"{name}_main"
    return f"{GO2RTC_URL}/api/ws?src={name}"
